mapper.select:
SELECT a.id, a.display_name FROM c2k_account a
JOIN c2k_candidate c ON c.tenant_id = a.tenant_id AND c.id = #{candidate}
WHERE a.tenant_id = #{tenant} AND position(lower(#{keyword}) in lower(a.display_name)) > 0
  AND  AND 
ORDER BY a.display_name, a.id LIMIT 20 OFFSET #{offset}

